caps=[('1s',2),('2s',2),('2p',6),('3s',2),('3p',6)]
def conf(n):
    out={}
    for s,c in caps:
        k=min(c,n); out[s]=k; n-=k
    return out
S=conf(16)
assert S=={'1s':2,'2s':2,'2p':6,'3s':2,'3p':4}
S2=conf(18)
assert S2=={'1s':2,'2s':2,'2p':6,'3s':2,'3p':6}
val=S['3s']+S['3p']
core=S['1s']+S['2s']+S['2p']
assert val==6 and core==10 and val+core==16
# Coulomb: smaller r gives larger force for same charges
assert 1/2**2>1/3**2
print('ALL_CHECKS_PASSED')

